begin; do $test$ declare a uuid;b uuid;v jsonb;before_work bigint;begin select id into a from sunshine_v4.works limit 1;select id into b from sunshine_v4.works where id<>a limit 1;v:=private.agent_cost_breakdown('2099-01-01','2099-01-01');before_work:=coalesce((v->'groups'->>'TRABALHO')::bigint,0);insert into sunshine_v4.expenses(description,category,scope,amount_cents,occurred_on,status,idempotency_key,created_by,allocations) values('__TEST_AGENT_COST__','MATERIAIS','SHARED',10000,'2099-01-01','PENDING',gen_random_uuid()::text,(select auth_user_id from sunshine_v4.team_members where active limit 1),jsonb_build_array(jsonb_build_object('workId',a,'amountCents',4000),jsonb_build_object('workId',b,'amountCents',6000)));v:=private.agent_cost_breakdown('2099-01-01','2099-01-01');if (v->'groups'->>'TRABALHO')::bigint-before_work<>10000 or not exists(select 1 from jsonb_array_elements(v->'works')x where x->>'work_id'=a::text and (x->>'amount_cents')::bigint=4000) then raise exception 'Manual split breakdown failed: %',v;end if;end $test$;select 'PASS: manual cost split across two works, integer cents and preserved total' result;rollback;
